<script setup lang="ts">
import {computed,onScopeDispose,provide,ref,shallowRef,watch} from 'vue'
import {can,currentProject,projectId} from '@/core/session'
import {ApiError,errorMessage,identityEpoch,onIdentityChange} from '@/core/http'
import AsyncState from '@/ui/AsyncState.vue'
import DeviceRulePreprocessBuilder from './DeviceRulePreprocessBuilder.vue'
import {deviceDataSourceContextKey,readDeviceDataSourceContext,commonDeviceDataStreams,deviceDataSourceProfile,type DeviceDataSourceContext} from './device-data-source-context'
import {sourceContract} from './rule-source-api'
import {sourceSelectionKey,type RuleSourceSelection} from './rule-source-selection'
import {createTypePreprocessor,recoverTypePreprocessor,readTypePreprocessor,knownPreprocessRejection,PreprocessOutcomeUnknown,makeTypePreprocessActivationIntent,activateTypePreprocessIntent,confirmTypePreprocessActivation,type TypePreprocessActivationIntent} from './preprocess-control-api'
import type {PreprocessCreationDraft} from './preprocess-version-editor'
const props=defineProps<{source:RuleSourceSelection;initialName:string;initialStreamIdentifier:string}>()
const emit=defineEmits<{created:[id:string];close:[];previous:[];busy:[value:boolean];locked:[value:boolean];denied:[cause:ApiError,uncertain:boolean]}>()
const sourceKey=computed(()=>sourceSelectionKey(props.source)),readable=computed(()=>!!projectId.value&&can('rule:manage')&&can('device:read')),allowed=computed(()=>readable.value&&currentProject.value?.status==='ACTIVE')
const context=shallowRef<DeviceDataSourceContext>(),loading=ref(false),busy=ref(false),builderLocked=ref(false),unknown=ref(false),error=ref(''),rejectedAttempt=ref<string>(),generation=ref(0)
const pending=shallowRef<{ruleId:string;draft:PreprocessCreationDraft;activation?:TypePreprocessActivationIntent;activationAttempted?:boolean;activationRejected?:boolean}>()
const scopeKey=computed(()=>`${identityEpoch()}:${generation.value}:${projectId.value}:device-data-create`),streams=computed(()=>context.value?commonDeviceDataStreams(context.value):[]),profile=computed(()=>context.value?deviceDataSourceProfile(context.value):undefined)
provide(deviceDataSourceContextKey,computed(()=>context.value))
let alive=true,controller:AbortController|undefined
function reset(){generation.value++;controller?.abort();context.value=undefined;loading.value=false;busy.value=false;builderLocked.value=false;unknown.value=false;error.value='';pending.value=undefined;rejectedAttempt.value=undefined}
function capture(){const turn=generation.value,epoch=identityEpoch(),project=projectId.value,key=sourceKey.value,scope={projectId:project,deviceTypeId:'',scopeKey:scopeKey.value,deviceSource:sourceContract(props.source)};return{scope,current:()=>alive&&turn===generation.value&&epoch===identityEpoch()&&project===projectId.value&&key===sourceKey.value&&readable.value}}
function denied(cause:unknown,uncertain:boolean){const actual=cause instanceof PreprocessOutcomeUnknown?cause.cause:cause;if(actual instanceof ApiError&&[401,403,404].includes(actual.status)){context.value=undefined;emit('denied',actual,uncertain)}}
async function load(){if(!readable.value||loading.value||busy.value||unknown.value||pending.value)return;const s=capture();controller?.abort();controller=new AbortController();loading.value=true;error.value='';try{const value=await readDeviceDataSourceContext(s.scope.projectId,s.scope.deviceSource,controller.signal);if(s.current())context.value=value}catch(cause){if(s.current()){error.value=errorMessage(cause);denied(cause,false)}}finally{if(s.current())loading.value=false}}
async function submit(intent:{scopeKey:string;source:RuleSourceSelection;attemptId:string;draft:PreprocessCreationDraft}){if(!allowed.value||!context.value||busy.value||unknown.value||intent.scopeKey!==scopeKey.value||sourceSelectionKey(intent.source)!==sourceKey.value)return;const s=capture();controller?.abort();controller=new AbortController();busy.value=true;error.value='';try{const value=await createTypePreprocessor(s.scope,intent.draft,intent.attemptId,s.current,controller.signal);if(s.current()){pending.value={ruleId:value.id,draft:intent.draft,activation:makeTypePreprocessActivationIntent(s.scope,value.facts,crypto.randomUUID()),activationAttempted:false};await activateCreated()}}catch(cause){if(s.current()){error.value=errorMessage(cause);if(knownPreprocessRejection(cause))rejectedAttempt.value=intent.attemptId;else{unknown.value=true;if(cause instanceof PreprocessOutcomeUnknown&&cause.ruleId)pending.value={ruleId:cause.ruleId,draft:intent.draft}}denied(cause,unknown.value)}}finally{if(s.current())busy.value=false}}
async function activateCreated(){const original=pending.value;if(!allowed.value||!original?.activation||original.activationAttempted)return;const s=capture();pending.value={...original,activationAttempted:true};busy.value=true;error.value='';try{await activateTypePreprocessIntent(s.scope,original.activation,s.current);if(s.current())emit('created',original.ruleId)}catch(cause){if(s.current()){error.value=errorMessage(cause);if(knownPreprocessRejection(cause)){error.value='规则已创建，但启用未完成。'+errorMessage(cause);pending.value={...original,activationAttempted:true,activationRejected:true};unknown.value=false}else unknown.value=true;denied(cause,unknown.value)}}finally{if(s.current())busy.value=false}}
async function recover(){const original=pending.value;if(!readable.value||busy.value||!original)return;const s=capture();busy.value=true;error.value='';try{if(original.activation){confirmTypePreprocessActivation(original.activation,await readTypePreprocessor(s.scope,original.ruleId,s.current));if(s.current())emit('created',original.ruleId)}else{const value=await recoverTypePreprocessor(s.scope,original.ruleId,original.draft,s.current);if(s.current()){pending.value={...original,activation:makeTypePreprocessActivationIntent(s.scope,value,crypto.randomUUID()),activationAttempted:false};unknown.value=false}}}catch(cause){if(s.current()){unknown.value=true;error.value=errorMessage(cause);denied(cause,true)}}finally{if(s.current())busy.value=false}}
watch([projectId,sourceKey,readable],()=>{reset();if(readable.value)void load()},{immediate:true});watch(busy,value=>emit('busy',value),{immediate:true,flush:'sync'});watch([loading,builderLocked,unknown,pending],()=>emit('locked',loading.value||builderLocked.value||unknown.value||!!pending.value),{immediate:true,flush:'sync'})
const dispose=onIdentityChange(reset);onScopeDispose(()=>{alive=false;controller?.abort();dispose();emit('busy',false);emit('locked',false)})
</script>
<template><section><AsyncState :forbidden="!readable" :loading="loading" :error="!context?error:undefined" @retry="load"><DeviceRulePreprocessBuilder v-if="context&&profile" :scope-key="scopeKey" :project-id="projectId" :source-selection="source" :initial-name="initialName" initial-kind="DATA_RPT" :initial-stream-identifier="initialStreamIdentifier" external-first-step :data-streams="streams" :source-device-kind="profile.deviceKind" :source-payload-protocol="profile.payloadProtocol" :gateway-data-available="context.members.every(member=>member.profile.type.deviceKind==='GATEWAY'&&member.profile.type.payloadProtocol==='STANDARD_GATEWAY')" :subdevice-address-allowed="context.members.every(member=>member.profile.type.deviceKind==='SUB_DEVICE')" :disabled="!allowed||busy||unknown||!!pending" :rejected-attempt="rejectedAttempt" @create-sources="submit" @cancel="emit('close')" @previous="emit('previous')" @locked="builderLocked=$event"/></AsyncState><el-alert v-if="context&&error" :title="unknown?'创建结果尚未完整核对，请勿重复创建。'+error:error" type="error" :closable="false"/><el-button v-if="unknown&&pending" :disabled="busy||!readable" @click="recover">读取原规则核对</el-button><el-button v-if="pending?.activation&&!pending.activationAttempted" :disabled="busy||!allowed" @click="activateCreated">继续完成启用</el-button><el-button v-if="pending?.activationRejected" :disabled="busy||!readable" @click="emit('created',pending.ruleId)">查看已创建规则</el-button><p v-if="unknown&&!pending">尚未取得规则ID，保留原草稿，不自动重发创建请求。</p></section></template>
